def d(i,j): return math.dist(coords[i], coords[j])
for name,i,j in [('Ir-H',1,0),('Ir-Ctop',1,2),('Ir-Cbottom',1,31),('Ir-Zn',1,60),('Zn-Cipso',60,61),('Ir-Ccentral',1,13),('Ir-Cterm',1,14),('C=C',13,14)]:
